const test = require('node:test');
const assert = require('node:assert/strict');
const { readTags } = require('../tags.cjs');
test('keeps every repeated tag in order', () => {
  assert.deepEqual(readTags('?tag=blue&tag=wide'), ['blue','wide']);
  assert.deepEqual(readTags('tag=red&x=1&tag=&tag=red'), ['red','','red']);
  assert.deepEqual(readTags('tag=A%26B&tag=two+words'), ['A&B','two words']);
});
test('missing and differently cased keys', () => {
  assert.deepEqual(readTags('Tag=other&tag='), ['']);
  assert.deepEqual(readTags('?x=1'), []);
  assert.deepEqual(readTags(''), []);
});

